const incoming = $input.all();
const result = [];

// Отдельный накопитель для каждого execution: параллельные вызовы не перезаписывают друг друга.
const sd = $getWorkflowStaticData('global');
if (!sd.attemptsByExecution || typeof sd.attemptsByExecution !== 'object') sd.attemptsByExecution = {};
const executionId = String($execution.id);
sd.attemptsByExecution[executionId] = [];

for (const element of incoming) {
  let pageUrl = String(element.json.url ?? '').trim();
  if (!pageUrl) {
    throw new Error('url не передан на вход сабворкфлоу');
  }

  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(pageUrl)) {
    pageUrl = 'https://' + pageUrl;
  }

  const parts = pageUrl.match(/^[a-z][a-z0-9+.-]*:\/\/([^\/?#]+)/i);
  const hostPort = parts ? parts[1] : '';
  const bareHost = hostPort.split('@').pop().split(':')[0];
  const domain = bareHost.toLowerCase().replace(/^www\./, '');

  if (!/^[a-z0-9.-]+$/.test(domain) || domain.indexOf('.') === -1) {
    throw new Error('некорректный url: ' + pageUrl);
  }

  const attemptsLimit = Math.max(1, Math.min(Number(element.json.max_attempts ?? 4), 5));
  result.push({ json: { url: pageUrl, domain: domain, max_attempts: attemptsLimit } });
}

return result;

const init = $('Init').first().json;
const rows = [...$('SQL champions').all(), ...$('SQL newbies').all()];
const seen = new Set();
const candidates = [];
for (const r of rows) {
  const j = r.json || {};
  if (!j.id || !j.ip) continue;
  if (seen.has(j.id)) continue;
  seen.add(j.id);
  candidates.push({
    id: j.id,
    ip: String(j.ip),
    ms: j.ms === null || j.ms === undefined ? 99999 : Number(j.ms),
  });
}
candidates.sort((a, b) => a.ms - b.ms);
return [{ json: { url: init.url, domain: init.domain, max_attempts: init.max_attempts, candidates: candidates } }];

const state = $('Combine').first().json;
const res = $input.first().json || {};
const results = Array.isArray(res.results) ? res.results : [];
const bare = (s) => String(s || '').replace(/^[a-z]+:\/\//i, '');

const byIp = new Map();
for (const c of state.candidates) {
  byIp.set(bare(c.ip), c);
}

const limit = Math.max(1, Math.min(state.max_attempts, 5));

// порог мягкий: живые прокси из пула отвечают и по 7-8 секунд
const MS_LIMIT = 10000;

// Фиксированный прокси: пробуется после пула живых и перед запросом без прокси.
// В max_attempts не входит. В proxy_lst его нет, поэтому статистика по нему не пишется.
const FIXED_PROXY = 'http://sinchrobelg.duckdns.org:42774';

const alive = results
  .filter((r) => {
    if (!r) return false;
    const fast = typeof r.ms === 'number' && r.ms <= MS_LIMIT;
    if (r.ok === true) return true;
    // прокси ответил HTTP-статусом (429/502/503) — он жив, просто тест не подтвердил IP
    return r.reachable === true && fast;
  })
  .sort((a, b) => {
    const verified = (b.ok ? 1 : 0) - (a.ok ? 1 : 0);
    if (verified !== 0) return verified;
    return (a.ms ?? 99999) - (b.ms ?? 99999);
  })
  .slice(0, limit - 1);

const out = [];

for (const r of alive) {
  const c = byIp.get(bare(r.proxy));
  out.push({
    json: {
      url: state.url,
      domain: state.domain,
      proxy_id: c ? c.id : null,
      proxy: r.proxy,
      ms: r.ms,
      verified: r.ok === true,
    },
  });
}

out.push({
  json: {
    url: state.url,
    domain: state.domain,
    proxy_id: null,
    proxy: FIXED_PROXY,
    ms: null,
    verified: false,
    fixed: true,
  },
});

out.push({
  json: {
    url: state.url,
    domain: state.domain,
    proxy_id: null,
    proxy: null,
    ms: 0,
    verified: false,
    checked: results.length,
    alive_count: alive.length,
  },
});

return out;

const result = $input.first().json || {};
const current = $('Loop Over Items').item.json || {};
const state = $('Combine').first().json;
const via = current.proxy || 'direct';

function mapOutcome(code, detail) {
  if (code === 'proxy_unreachable' || code === 'launch_failed') return 'proxy_error';
  // TLS-MITM: прокси подменяет сертификат — виноват прокси, а не сайт
  if (code === 'navigation_failed' && /SEC_ERROR|ERR_CERT|PR_END_OF_FILE|PR_CONNECT_RESET/i.test(String(detail || ''))) return 'proxy_error';
  if (code === 'timeout') return 'timeout';
  return 'target_error';
}

const sd = $getWorkflowStaticData('global');
if (!sd.attemptsByExecution || typeof sd.attemptsByExecution !== 'object') sd.attemptsByExecution = {};
const executionId = String($execution.id);
if (!Array.isArray(sd.attemptsByExecution[executionId])) sd.attemptsByExecution[executionId] = [];

let attempt;
let ok = false;
let outcome;

if (result.ok === true && result.challenge_cleared === true) {
  ok = true;
  outcome = 'ok';
  attempt = { proxy: via, result: 'ok', waited_ms: result.waited_ms, detected_by: result.detected_by };
} else if (result.ok === true && result.challenge_cleared === false) {
  outcome = 'challenge';
  attempt = { proxy: via, result: 'challenge', detected_by: result.detected_by, waited_ms: result.waited_ms };
} else if (typeof result.error === 'string') {
  outcome = mapOutcome(result.error, result.detail);
  attempt = { proxy: via, result: result.error, detail: String(result.detail || '').slice(0, 200) };
} else if (result.error && typeof result.error === 'object') {
  const msg = String(result.error.message || result.error.code || 'request failed').slice(0, 200);
  outcome = 'target_error';
  attempt = { proxy: via, result: 'request_failed', detail: msg };
} else {
  outcome = 'target_error';
  attempt = { proxy: via, result: 'unknown_response' };
}

sd.attemptsByExecution[executionId].push(attempt);

// outcome / proxy_id / url / ms / waited_ms / detected_by / http_status_raw
// нужны только write-ветками, Collect их не читает.
return [{
  json: {
    final: ok,
    proxy: via,
    title: ok ? result.title : null,
    http_status: ok ? result.http_status : null,
    html: ok ? result.html : null,
    outcome: outcome,
    proxy_id: current.proxy_id || null,
    domain: state.domain,
    url: state.url,
    ms: typeof current.ms === 'number' ? current.ms : null,
    waited_ms: typeof result.waited_ms === 'number' ? result.waited_ms : null,
    detected_by: result.detected_by || null,
    http_status_raw: typeof result.http_status === 'number' ? result.http_status : null,
  },
}];

const state = $('Combine').first().json;

const sd = $getWorkflowStaticData('global');
const executionId = String($execution.id);
const attempts = Array.isArray(sd.attemptsByExecution?.[executionId])
  ? sd.attemptsByExecution[executionId]
  : [];
delete sd.attemptsByExecution?.[executionId];

const items = $input.all().map((i) => i.json || {});
const success = items.find((j) => j && j.final === true) || null;

return [{
  json: {
    ok: !!success,
    url: state.url,
    domain: state.domain,
    error: success ? null : 'all_attempts_failed',
    title: success ? success.title : null,
    http_status: success ? success.http_status : null,
    html: success ? success.html : null,
    attempts: attempts,
  },
}];

try {
  const res = $input.first().json || {};
  const results = Array.isArray(res.results) ? res.results : [];
  const state = $('Combine').first().json;

  const IP4 = /^(?:\d{1,3}\.){3}\d{1,3}$/;
  const IP6 = /^[0-9a-fA-F:]{2,45}$/;
  const CODES = ['connect_timeout', 'read_timeout', 'refused', 'reset', 'dns', 'tls', 'timeout', 'other'];

function sqlStr(v) {
  if (v === null || v === undefined) return 'NULL';
  return "'" + String(v)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\0/g, '\\0')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\x1a/g, '\\Z') + "'";
}

  const bare = (s) => String(s || '').replace(/^[a-z]+:\/\//i, '');

  const byIp = new Map();
  for (const c of state.candidates) {
    byIp.set(bare(c.ip), c.id);
  }

  const out = [];
  for (const r of results) {
    if (!r) continue;

    const idNum = Number(byIp.get(bare(r.proxy)));
    if (!isFinite(idNum) || idNum <= 0) continue;

    const good = (r.ok === true || r.reachable === true) ? 1 : 0;

    // exit_ip приходит из ответа api.ipify.org / icanhazip.com — это НЕдоверенный
    // ввод (app.py берёт строку из JSON до 64 символов без проверки). Пропускаем
    // только то, что реально похоже на IPv4/IPv6, иначе NULL.
    let exitIp = null;
    const raw = typeof r.exit_ip === 'string' ? r.exit_ip.trim() : '';
    if (raw && (IP4.test(raw) || (raw.indexOf(':') !== -1 && IP6.test(raw)))) {
      exitIp = raw;
    }

    let code = 'other';
    const rawCode = typeof r.error_code === 'string' ? r.error_code : '';
    if (CODES.indexOf(rawCode) !== -1) code = rawCode;

    const msNum = typeof r.ms === 'number' && isFinite(r.ms) ? Math.round(r.ms) : null;

    out.push({
      json: {
        id: idNum,
        good: good,
        ms_sql: msNum === null ? 'NULL' : String(msNum),
        exit_ip_sql: exitIp === null ? 'NULL' : sqlStr(exitIp),
        err_sql: good === 1 ? 'NULL' : sqlStr(code),
      },
    });
  }
  // Даже если проверка не вернула ни одного прокси, отдаём безопасный no-op UPDATE (id=0).
  return out.length ? out : [{ json: { id: 0, good: 0, ms_sql: 'NULL', exit_ip_sql: 'NULL', err_sql: 'NULL' } }];
} catch (e) {
  return [{ json: { id: 0, good: 0, ms_sql: 'NULL', exit_ip_sql: 'NULL', err_sql: 'NULL' } }];
}

try {
  const c = $input.first().json || {};

  const pid = Number(c.proxy_id);
  if (!c.proxy_id || !isFinite(pid) || pid <= 0) return [{ json: { domain: '', proxy_id: 0, ok: 0, bad: 0, err_sql: 'NULL' } }];
  if (!/^[a-z0-9.-]+$/.test(String(c.domain || ''))) return [{ json: { domain: '', proxy_id: 0, ok: 0, bad: 0, err_sql: 'NULL' } }];

  // ok      = антибот пустил;
  // bad     = челлендж, то есть именно домен не пустил этот прокси.
  // Сетевые ошибки прокси (proxy_error/timeout) сюда НЕ входят: они пишутся
  // в proxy_lst, иначе fail_count выкинет прокси из-за обрыва связи.
  const ok = c.outcome === 'ok' ? 1 : 0;
  const bad = c.outcome === 'challenge' ? 1 : 0;

  return [{
    json: {
      domain: String(c.domain),
      proxy_id: pid,
      ok: ok,
      bad: bad,
      err_sql: bad === 1 ? "'challenge'" : 'NULL',
    },
  }];
} catch (e) {
  return [{ json: { domain: '', proxy_id: 0, ok: 0, bad: 0, err_sql: 'NULL' } }];
}

try {
  const c = $input.first().json || {};

  const pid = Number(c.proxy_id);
  // proxy_log.proxy_id — INT UNSIGNED NOT NULL, попытку direct логировать некуда
  if (!c.proxy_id || !isFinite(pid) || pid <= 0) return [{ json: { proxy_id: 0, domain: '', url_sql: 'NULL', result: 'target_error', http_sql: 'NULL', waited_sql: 'NULL', detected_sql: 'NULL', ms_sql: 'NULL' } }];
  if (!/^[a-z0-9.-]+$/.test(String(c.domain || ''))) return [{ json: { proxy_id: 0, domain: '', url_sql: 'NULL', result: 'target_error', http_sql: 'NULL', waited_sql: 'NULL', detected_sql: 'NULL', ms_sql: 'NULL' } }];

  const RESULTS = ['ok', 'challenge', 'proxy_error', 'target_error', 'timeout'];
  const result = RESULTS.indexOf(c.outcome) !== -1 ? c.outcome : 'target_error';

function sqlStr(v) {
  if (v === null || v === undefined) return 'NULL';
  return "'" + String(v)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\0/g, '\\0')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\x1a/g, '\\Z') + "'";
}

  const httpStatus = typeof c.http_status_raw === 'number' ? Math.round(c.http_status_raw) : null;
  const waitedMs = typeof c.waited_ms === 'number' ? Math.round(c.waited_ms) : null;
  const ms = typeof c.ms === 'number' ? Math.round(c.ms) : null;
  const detected = (typeof c.detected_by === 'string' && /^[a-z0-9_]{1,32}$/.test(c.detected_by))
    ? c.detected_by
    : null;

  return [{
    json: {
      proxy_id: pid,
      domain: String(c.domain),
      url_sql: sqlStr(String(c.url || '').slice(0, 1024)),
      result: result,
      http_sql: httpStatus === null ? 'NULL' : String(httpStatus),
      waited_sql: waitedMs === null ? 'NULL' : String(waitedMs),
      detected_sql: detected === null ? 'NULL' : sqlStr(detected),
      ms_sql: ms === null ? 'NULL' : String(ms),
    },
  }];
} catch (e) {
  return [{ json: { proxy_id: 0, domain: '', url_sql: 'NULL', result: 'target_error', http_sql: 'NULL', waited_sql: 'NULL', detected_sql: 'NULL', ms_sql: 'NULL' } }];
}
